# owner: platform
"""Seating plans: students sorted by name, filled by row."""

from typing import List
from rosterkit.models import Student


def _check_input(students: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (
        student.last_name.lower(),
        student.first_name.lower()
    )


def _split_rows(
    students: List[Student],
    seats: int
) -> List[List[Student]]:
    return [
        students[start:start + seats]
        for start in range(0, len(students), seats)
    ]


def _format_row(index: int, row: List[Student]) -> str:
    names = " | ".join(item.display_name for item in row)
    return f"Row {index}: {names}"


# ---
def seating_rows(
    students: List[Student],
    seats: int
) -> List[str]:
    _check_input(students, seats)
    ordered = sorted(students, key=_sort_key)
    rows = _split_rows(ordered, seats)
    return [
        _format_row(index, row)
        for index, row in enumerate(rows, 1)
    ]

